<script>
(function(){const form=document.getElementById('plan-form'),provider=document.getElementById('provider-type'),json=document.getElementById('entitlements-json');let current={};try{current=JSON.parse(json.value||'{}')}catch(e){}function refresh(){document.querySelectorAll('.entitlement-option').forEach(el=>{el.style.display=el.dataset.provider===provider.value?'':'none'});document.querySelectorAll('.entitlement-value').forEach(input=>{const key=input.dataset.key;if(input.dataset.kind==='limit')input.value=(provider.value===input.closest('.entitlement-option').dataset.provider&&current[key]!==undefined)?current[key]:'';else input.checked=provider.value===input.closest('.entitlement-option').dataset.provider&&current[key]===true})}provider.addEventListener('change',()=>{current={};refresh()});form.addEventListener('submit',()=>{const result={};document.querySelectorAll('.entitlement-option').forEach(el=>{if(el.dataset.provider!==provider.value)return;el.querySelectorAll('.entitlement-value').forEach(input=>{if(input.dataset.kind==='limit'){if(input.value!=='')result[input.dataset.key]=Number(input.value)}else if(input.checked)result[input.dataset.key]=true})});json.value=JSON.stringify(result)});refresh()})();
</script>
